 '90/90 with a fold':[
  ['13.1','both legs in the same place, on the floor, in every frame',C=>{const r=fixed(C,['knL','knR','ftL','ftR'],0.5);return r===true?all(C,f=>ok(C.gap(f,'knL')<=4&&C.gap(f,'knR')<=4&&C.gap(f,'ftL')<=3&&C.gap(f,'ftR')<=3,'a knee or foot is off the floor')):r;}],
  ['13.2','front shin across the body and back shin pointing straight behind',C=>{const f=C.F[0],fs=nrm(sub(f.j.ftR,f.j.knR)),bs=nrm(sub(f.j.ftL,f.j.knL));return ok(Math.abs(dot(fs,C.lat(f)))>=0.85&&dot(bs,C.fwd(f))<=-0.85,`front shin ${f1(Math.abs(dot(fs,C.lat(f))))} across, back shin ${f1(-dot(bs,C.fwd(f)))} behind`);}],
  ['13.3','both knees bent to about a right angle in every frame',C=>all(C,f=>ok(Math.abs(knee(C,f,'L')-90)<=12&&Math.abs(knee(C,f,'R')-90)<=12,`knees ${f1(knee(C,f,'L'))} / ${f1(knee(C,f,'R'))}`))],
  ['13.4','a frame with the trunk upright',C=>some(C,f=>ok(C.tilt(f,'pelvis','neck')<=10))],
  ['13.5','a frame with the trunk clearly tipped forward over the front shin',C=>some(C,f=>ok(C.pitch(f,'pelvis','neck')>=35&&C.along(f,'neck','pelvis',C.fwd(f))>8))],
  ['13.6','the back is a straight line from pelvis to head in every frame',C=>straightBack(C,8)],
  ['13.7','the trunk stays centred (no sideways collapse or twist)',C=>all(C,f=>ok(Math.abs(f.pose.tw||0)<=3&&Math.abs(f.pose.sl||0)<=3,'trunk twists or side-bends'))],
  ['13.x1','critique S4: the Z of the legs reads from the camera. Both shins and both thighs show at least 45% of their length',C=>{const f=C.F[0];let w=1,wk='';[['hpL','knL'],['knL','ftL'],['hpR','knR'],['knR','ftR']].forEach(([a,b])=>{const r=C.sdist(f,a,b)/(dist(f.j[a],f.j[b])*C.m.fit.sc);if(r<w){w=r;wk=a+'-'+b;}});return ok(w>=0.45,`${wk} shows ${(w*100).toFixed(0)}% of its length`);}],
 ],
